SELECT u.member_id AS row_id, u.member_id, u.type_cd, mc.name AS member_type_name, u.nickname, u.gender_cd, CONVERT_FROM(DECRYPT(DECODE(u.name,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') AS member_name, CONVERT_FROM(DECRYPT(DECODE(u.phone,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') AS phone, CONVERT_FROM(DECRYPT(DECODE(u.email,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') AS email, CONVERT_FROM(DECRYPT(DECODE(u.birth,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') AS birth, u.status_cd, sc.name AS status_cd_name, u.use_yn FROM member u LEFT JOIN code mc ON mc.code_id = u.type_cd AND mc.p_code_id = 'MEM00' LEFT JOIN code sc ON sc.code_id = u.status_cd AND sc.p_code_id = 'STATUS00' WHERE u.use_yn = 'Y' AND u.type_cd = #{typeCd} AND u.status_cd = #{statusCd}
AND (u.member_id LIKE '%' || #{filterKeyword} || '%' OR CONVERT_FROM(DECRYPT(DECODE(u.name,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') LIKE '%' || #{filterKeyword} || '%')
ORDER BY u.reg_dt DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM member WHERE use_yn = 'Y'
AND type_cd = #{typeCd}
AND status_cd = #{statusCd}

    AND (member_id LIKE '%' || #{filterKeyword} || '%'
         OR CONVERT_FROM(DECRYPT(DECODE(name,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') LIKE '%' || #{filterKeyword} || '%')

