UPDATE member SET
    password = #{password}, last_upd_dt = NOW(),
    password_expire_dt = NOW() + (COALESCE((SELECT password_expire_days FROM config LIMIT 1), 90) * INTERVAL '1 day'),
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE member_id = #{rowId}

UPDATE member SET
    password_expire_dt = NOW() + (COALESCE((SELECT password_expire_days FROM config LIMIT 1), 90) * INTERVAL '1 day'),
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE member_id = #{memberId}

UPDATE member SET use_yn = 'N', withdraw_dt = COALESCE(withdraw_dt, NOW()),
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE member_id = #{rowId}

UPDATE member SET status_cd = 'STATUS01', dormant_dt = NULL, last_login_dt = NOW(),
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE member_id = #{memberId} AND status_cd = 'STATUS04'
